\label{def:Hstar-operators}
Let $\mathbb{A}\subseteq\mathbb{X}$. The
\emph{$H^{*}$-closure} of $\mathbb{A}$ is defined by
\begin{equation}
H^{*}\operatorname{Cl}(\mathbb{A})
=
\bigcap
\left\{
\mathbb{F}\in H^{*}C(\mathbb{X}):
\mathbb{A}\subseteq\mathbb{F}
\right\},
\label{eq:Hstar-closure}
\end{equation}
and the \emph{$H^{*}$-interior} of $\mathbb{A}$ is defined by
\begin{equation}
H^{*}\operatorname{Int}(\mathbb{A})
=
\bigcup
\left\{
\mathbb{U}\in H^{*}O(\mathbb{X}):
\mathbb{U}\subseteq\mathbb{A}
\right\}.
\label{eq:Hstar-interior}
\end{equation}

\label{prop:Hstar-duality}
For every $\mathbb{A}\subseteq\mathbb{X}$,
\begin{equation}
H^{*}\operatorname{Int}(\mathbb{A})
=
\mathbb{X}\setminus
H^{*}\operatorname{Cl}
(\mathbb{X}\setminus\mathbb{A}).
\label{eq:Hstar-int-cl-duality}
\end{equation}
Equivalently,
\begin{equation}
H^{*}\operatorname{Cl}(\mathbb{A})
=
\mathbb{X}\setminus
H^{*}\operatorname{Int}
(\mathbb{X}\setminus\mathbb{A}).
\label{eq:Hstar-cl-int-duality}
\end{equation}

\label{thm:Hstar-topology-characterization}
Let $(\mathbb{X},\tau)$ be a topological space such that
$H^{*}C(\mathbb{X})$ is closed under arbitrary intersections.
Then the following statements are equivalent:
\begin{enumerate}[label=(\roman*)]

    \item $\Gamma_{H^{*}}=H^{*}O(\mathbb{X})$ is an ordinary
    topology on $\mathbb{X}$;

    \item $H^{*}O(\mathbb{X})$ is closed under finite intersections;

    \item $H^{*}C(\mathbb{X})$ is closed under finite unions.

\end{enumerate}

\label{prop:Hstar-union-intersection}
For all $\mathbb{A},\mathbb{B}\subseteq\mathbb{X}$,
\begin{equation}
H^{*}\operatorname{Cl}(\mathbb{A})
\cup
H^{*}\operatorname{Cl}(\mathbb{B})
\subseteq
H^{*}\operatorname{Cl}(\mathbb{A}\cup\mathbb{B}),
\label{eq:Hstar-closure-union-inclusion}
\end{equation}
and
\begin{equation}
H^{*}\operatorname{Int}(\mathbb{A}\cap\mathbb{B})
\subseteq
H^{*}\operatorname{Int}(\mathbb{A})
\cap
H^{*}\operatorname{Int}(\mathbb{B}).
\label{eq:Hstar-interior-intersection-inclusion}
\end{equation}

\label{thm:Hstar-Kuratowski}
Suppose that the equivalent conditions of
Theorem~\ref{thm:Hstar-topology-characterization} hold. Then, for all
$\mathbb{A},\mathbb{B}\subseteq\mathbb{X}$,
\begin{equation}
H^{*}\operatorname{Cl}(\mathbb{A}\cup\mathbb{B})
=
H^{*}\operatorname{Cl}(\mathbb{A})
\cup
H^{*}\operatorname{Cl}(\mathbb{B}),
\label{eq:Hstar-closure-finite-union}
\end{equation}
and
\begin{equation}
H^{*}\operatorname{Int}(\mathbb{A}\cap\mathbb{B})
=
H^{*}\operatorname{Int}(\mathbb{A})
\cap
H^{*}\operatorname{Int}(\mathbb{B}).
\label{eq:Hstar-interior-finite-intersection}
\end{equation}

\label{prop:Hstar-separation-chain}
For a topological space $(\mathbb{X},\tau)$,
\[
H^{*}\text{-}T_{2}
\Longrightarrow
H^{*}\text{-}T_{1}
\Longrightarrow
H^{*}\text{-}T_{0}.
\]

\label{thm:Hstar-T1-singletons}
The space $(\mathbb{X},\tau)$ is $H^{*}$-$T_{1}$ if and only if
every singleton subset of $\mathbb{X}$ is $H^{*}$-closed.

\label{thm:Hstar-T0-associated}
The space $(\mathbb{X},\tau)$ is $H^{*}$-$T_{0}$ if and only if
$(\mathbb{X},\tau_{H^{*}})$ is a $T_{0}$ space.

\label{thm:Hstar-T1-associated}
The space $(\mathbb{X},\tau)$ is $H^{*}$-$T_{1}$ if and only if
$(\mathbb{X},\tau_{H^{*}})$ is a $T_{1}$ space.

\label{thm:Hstar-T2-associated}
The space $(\mathbb{X},\tau)$ is $H^{*}$-$T_{2}$ if and only if
$(\mathbb{X},\tau_{H^{*}})$ is Hausdorff.

\label{thm:Hstar-regular-associated}
The space $(\mathbb{X},\tau)$ is $H^{*}$-regular if and only if
$(\mathbb{X},\tau_{H^{*}})$ is regular.

\label{cor:Hstar-T3-associated}
The space $(\mathbb{X},\tau)$ is $H^{*}$-$T_{3}$ if and only if
$(\mathbb{X},\tau_{H^{*}})$ is $T_{3}$.

\label{thm:Hstar-normal-associated}
The space $(\mathbb{X},\tau)$ is $H^{*}$-normal if and only if
$(\mathbb{X},\tau_{H^{*}})$ is normal.

\label{cor:Hstar-T4-associated}
The space $(\mathbb{X},\tau)$ is $H^{*}$-$T_{4}$ if and only if
$(\mathbb{X},\tau_{H^{*}})$ is $T_{4}$.

\label{thm:Hstar-completely-regular-associated}
The space $(\mathbb{X},\tau)$ is $H^{*}$-completely regular if and
only if $(\mathbb{X},\tau_{H^{*}})$ is completely regular.

\label{def:Hstar-Tychonoff}
An $H^{*}$-completely regular $H^{*}$-$T_{1}$ space is called an
\emph{$H^{*}$-Tychonoff space}.

\label{cor:Hstar-Tychonoff-associated}
The space $(\mathbb{X},\tau)$ is $H^{*}$-Tychonoff if and only if
$(\mathbb{X},\tau_{H^{*}})$ is Tychonoff.

\label{prop:finite-original-not-T0}
The original space $(\mathbb{X},\tau)$ of
Example~\ref{ex:finite-discrete-Hstar} is not $T_{0}$.

\label{prop:infinite-original-not-T0}
The original space $(\mathbb{X},\tau)$ in
Example~\ref{ex:infinite-discrete-Hstar} is not $T_{0}$.
